-- The profiles themselves live under `social-links` in _quarto.yml, which also
-- feeds the structured data's "sameAs" list (_filters/structured-data.lua).
-- me: true adds rel="me" (two-way identity links for Mastodon, Threads,
-- GitHub, and ORCID).

local function escape(s)
  return (s:gsub("&", "&amp;"):gsub('"', "&quot;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
end

local function svg(name)
  local icon = icons[name]
  if not icon then
    local known = {}
    for key in pairs(icons) do known[#known + 1] = key end
    table.sort(known)
    error("Unknown icon '" .. name .. "'. Known icons: " .. table.concat(known, ", "))
  end
  -- Size and color are attributes so icons render right even before (or
  -- without) the stylesheet: 1em tall, width from the viewBox aspect ratio.
  local w, h = icon.viewBox:match("^%S+ %S+ (%S+) (%S+)$")
  local width = string.format("%.3gem", tonumber(w) / tonumber(h))
  return '<svg class="icon" viewBox="' .. icon.viewBox .. '" width="' .. width ..
    '" height="1em" fill="currentColor" aria-hidden="true" focusable="false"><path d="' ..
    icon.d .. '"/></svg>'
end

-- A <nav> is block-level, so emit a block when the shortcode stands alone.
local function raw(html, context)
  if context == "block" then
    return pandoc.RawBlock("html", html)
  end
  return pandoc.RawInline("html", html)
end

return {
  ["icon"] = function(args, kwargs, meta, raw_args, context)
    return raw(svg(pandoc.utils.stringify(args[1])), context)
  end,

  ["social-links"] = function(args, kwargs, meta, raw_args, context)
    local class = pandoc.utils.stringify(kwargs["class"] or "")
    if class == "" then class = "social-icons" end
    local items = {}
    for _, link in ipairs(meta["social-links"] or {}) do
      local me = link.me == true
      items[#items + 1] = '  <a href="' .. escape(pandoc.utils.stringify(link.url)) ..
        '" target="_blank" rel="' .. (me and "me noopener" or "noopener") ..
        '" aria-label="' .. escape(pandoc.utils.stringify(link.label)) ..
        '">' .. svg(pandoc.utils.stringify(link.icon)) .. '</a>'
    end
    if #items == 0 then error("No social-links found in _quarto.yml") end
    return raw('<nav class="' .. escape(class) .. '" aria-label="Social links">\n' ..
      table.concat(items, "\n") .. '\n</nav>', context)
  end,
}
